// Sandbox sample data tests (v1.3 plan Task 12, spec §6.8). The
// weak-support sample at public/samples/weak-support.fasta is
// regenerated byte-identically by scripts/samples/weak_support.py
// (seed 5), and its premise — a seeded run showing at least one
// support under 50% — is checked against the real engine here.

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { engine } from "./engine";

const SAMPLE = "public/samples/weak-support.fasta";

describe("weak-support sample (spec §6.8)", () => {
  it("scripts/samples/weak_support.py regenerates the file byte-identically", () => {
    const before = readFileSync(SAMPLE);
    execFileSync("python3", ["../scripts/samples/weak_support.py"], {
      stdio: "pipe",
    });
    const after = readFileSync(SAMPLE);
    expect(Buffer.compare(before, after)).toBe(0);
  });

  it("is 6 taxa A–F of 120 DNA sites", () => {
    const aln = engine.parseFasta(readFileSync(SAMPLE, "utf8"));
    if (!aln.ok) throw new Error("sample did not parse");
    expect(aln.value.labels).toEqual(["A", "B", "C", "D", "E", "F"]);
    expect(aln.value.alphabet).toBe("dna");
    for (const s of aln.value.seqs) expect(s).toHaveLength(120);
  });

  it("a seeded run shows at least one support below 50%", () => {
    const aln = engine.parseFasta(readFileSync(SAMPLE, "utf8"));
    if (!aln.ok) throw new Error("sample did not parse");
    const m = engine.distances(aln.value, "Jc69");
    if (!m.ok) throw new Error("distances failed");
    const built = engine.buildTree(m.value, "Nj", { trace: false });
    if (!built.ok) throw new Error("build failed");
    const tally = engine.bootstrapBatch(
      aln.value,
      "Jc69",
      "Nj",
      1,
      0,
      100,
    );
    if (!tally.ok) throw new Error("bootstrap failed");
    const support = engine.supportOnTree(built.value.tree, tally.value);
    if (!support.ok) throw new Error("support failed");
    const values = support.value.branches
      .map((b, i) => ({ b, n: support.value.nodes[i] }))
      .filter(({ b, n }) => n.parent !== null && b.support !== null)
      .map(({ b }) => b.support as number);
    expect(values.length).toBeGreaterThan(0);
    expect(Math.min(...values)).toBeLessThan(0.5);
  });
});
